function estimateRecipeMilkEquivalent(sku){const size=String(sku||'').match(/(\d+(?:\.\d+)?)\s*(kg|g|ml|l)\b/i);if(!size)return null;const amount=Number(size[1]),unit=size[2].toLowerCase(),kg=unit==='kg'?amount:unit==='g'||unit==='ml'?amount/1000:amount;const name=String(sku||'').toLowerCase();if(/paneer/.test(name))return {litresPerUnit:kg/.16,fatPercent:4.5,snfPercent:8.5,source:'16% draft milk yield; verify plant recipe'};if(/buttermilk|chaas/.test(name))return {litresPerUnit:kg,fatPercent:3,snfPercent:8.5,source:'Finished volume as milk-equivalent proxy; verify recipe'};if(/dahi|curd|yogurt/.test(name))return {litresPerUnit:kg*1.03,fatPercent:3,snfPercent:8.5,source:'1.03 L/kg draft yield; verify standardization'};if(/ghee/.test(name))return {litresPerUnit:kg*.995/(.04*.9),fatPercent:4,snfPercent:8.5,source:'4% fat and 90% recovery estimate'};if(/butter/.test(name))return {litresPerUnit:kg*.8/(.04*.9),fatPercent:4,snfPercent:8.5,source:'4% fat and 90% recovery estimate'};if(/milk/.test(name))return {litresPerUnit:kg,fatPercent:3,snfPercent:8.5,source:'1 L/L draft yield; verify product standard'};return null}
