 const totals=filtered.reduce((sum,row)=>sum+Number(cadence==='dmef'?row.forecast||0:row.forecast7d||0),0),chart=cadence==='dmef'?qcomDailyChart(filtered,filters.sku):qcomWeeklyChart(filtered,filters.sku);
