 const tabs=`<div class="qcom-cadence-tabs" role="tablist" aria-label="Q-Com planning cadence"><button class="qcom-cadence-tab ${cadence==='dmef'?'active':''}" role="tab" aria-selected="${cadence==='dmef'}" data-qcom-cadence="dmef"><span>Daily · DMEF</span><small>Short shelf life · dark-store replenishment</small></button><button class="qcom-cadence-tab ${cadence==='weekly'?'active':''}" role="tab" aria-selected="${cadence==='weekly'}" data-qcom-cadence="weekly"><span>Weekly · Non-DMEF</span><small>Longer shelf life · fulfilment-centre planning</small></button></div>`;
