function defaultFarmerLanguage(){const key='doordarshi-farmer-language-defaulted';try{if(localStorage.getItem(key)||localStorage.getItem('__GT_TRANSLATE_LANGS'))return;localStorage.setItem(key,'1')}catch{return}let tries=0;const apply=()=>{if(typeof window.doGTranslate==='function'){window.doGTranslate('en|gu');const select=$('.gtranslate_wrapper select');if(select&&[...select.options].some(option=>option.value==='en|gu'))select.value='en|gu';return}if(++tries<20)setTimeout(apply,250)};apply()}
