async function start(){
 if(location.protocol==='file:'){location.replace('http://127.0.0.1:4173/');return}
 try{const response=await fetch('/api/session');if(!response.ok){location.replace('/');return}currentUser=await response.json();state.geminiConfigured=Boolean((await fetch('/api/gemini/status').then(r=>r.json()).catch(()=>({}))).configured);activeFarmerId=currentUser.role==='farmer'?currentUser.farmerId:'F-1001';state.farmerRecommendation=currentUser.role==='farmer'?((await fetch('/api/farmer/loan-plan').then(r=>r.json()).catch(()=>({}))).recommendation||null):null;const bankStatus=await fetch(`/api/bank/status?farmerId=${encodeURIComponent(activeFarmerId)}`).then(r=>r.json()).catch(()=>({}));state.consent=Boolean(bankStatus.granted);state.repayment=Boolean(bankStatus.repaymentOptIn);state.bankRequest=bankStatus.request?.status==='pending';state.bankRequestDetails=bankStatus.request||null;state.consentDetails=bankStatus.granted?{purpose:bankStatus.purpose,fieldLabels:bankStatus.fieldLabels,purposeKey:bankStatus.purposeKey}:null;state.bankPurpose=bankStatus.request?.purposeKey||bankStatus.purposeKey||'advance';state.consentedProfile=currentUser.role==='operator'&&state.consent?await fetch(`/api/bank/profile?farmerId=${encodeURIComponent(activeFarmerId)}`).then(r=>r.ok?r.json():null).catch(()=>null):null;state.role=currentUser.role==='farmer'?'farmer':'tower';bindShell();render()}
 catch{document.querySelector('.wrap').innerHTML='<article class="panel"><h2>Sign in required</h2><p>Sign in through the workspace access page to continue.</p></article>'}
}
